#!/usr/bin/env python3
"""Show the operations behind every numerical answer in the three exams."""
from pathlib import Path
import sys,json,math
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from solution_steps import numeric_steps
BOOK=ROOT/'books/tecnologia-aeroespacial'
ROUTES={1:(
 r'Primero se obtiene el estado ISA con la altitud geopotencial. Después, la ley del gas permite calcular ambas densidades y Arquímedes cierra el equilibrio. En el Pitot se despeja Mach de la relación isentrópica antes de calcular TAS; continuidad constituye un balance separado.',
 [('Tg','288.15-.0065*3500','K','Integrar el gradiente troposférico.'),('pg','101325*(Tg/288.15)**(9.80665/(287.05287*.0065))','Pa','Integrar equilibrio hidrostático y gas perfecto.'),('rg','pg/(287.05287*Tg)','kg/m**3','Densidad del aire.'),('rh','pg/(2077.1*Tg)','kg/m**3','Densidad del helio, con su propia constante de gas.'),('mu','(rg-rh)*450-100','kg','Despejar carga del balance de empuje y pesos, incluyendo helio.'),('Fnet','5*9.80665','N','Restar cinco kilogramos de carga al equilibrio.'),('Tp','288.15-.0065*5500','K','Estado ISA del segundo vehículo.'),('pp','101325*(Tp/288.15)**(9.80665/(287.05287*.0065))','Pa','Presión estática ISA.'),('rp','pp/(287.05287*Tp)','kg/m**3','Densidad local.'),('M','sqrt(2/(1.4-1)*((53800/pp)**((1.4-1)/1.4)-1))','','Aislar Mach; comprobar que es menor que uno.'),('a','sqrt(1.4*287.05287*Tp)','m/s','Velocidad local del sonido.'),('V','M*a','m/s','TAS compresible.'),('Vi','sqrt(2*(53800-pp)/rp)','m/s','Aplicar por separado la aproximación incompresible.'),('error','100*(Vi/V-1)','','Error relativo en porcentaje.'),('ptback','pp*(1+.2*M**2)**3.5','Pa','Reconstruir presión total como comprobación.'),('md','1.15*.5*80','kg/s','Continuidad: entrada másica.'),('V2','md/(1.05*.35)','m/s','Despejar velocidad de salida y verificar el mismo caudal.')]),
2:(r'La geometría fija superficie y alargamiento antes de evaluar la polar. El equilibrio vertical fija el coeficiente de sustentación; de él salen incidencia, resistencia y potencia. Para buscar el mínimo se escribe $D=AV^2+B/V^2$, se deriva y se impone $AV^2=B/V^2$. Las raíces de equilibrio son las de la cuadrática en $V^2$ y exigen discriminante no negativo.',
 [('S','12*2.10*(1+.50)/2','m**2','Área del trapecio.'),('AR','12**2/S','','Alargamiento geométrico.'),('Ki','1/(pi*.91*AR)','','Coeficiente de resistencia inducida.'),('K','Ki+.007','','Sumar término dependiente del perfil.'),('eO','1/(pi*AR*K)','','Despejar eficiencia global; difiere de la eficiencia de sustentación.'),('T','288.15-.0065*2500','K','ISA local.'),('p','101325*(T/288.15)**(9.80665/(287.05287*.0065))','Pa','Presión ISA.'),('rho','p/(287.05287*T)','kg/m**3','Densidad local.'),('qS','.5*rho*72**2*S','N','Escala de fuerza aerodinámica.'),('CL','34000/qS','','Imponer sustentación igual al peso.'),('a','6/(1+6/(pi*.91*AR))','1/rad','Pendiente tridimensional del modelo lineal.'),('alpha','-2+CL/a*180/pi','degree','Convertir el incremento angular a grados y sumar ángulo de sustentación nula.'),('CDi','Ki*CL**2','','Parte inducida.'),('CDp','.007*CL**2','','Parte de perfil dependiente de sustentación.'),('CD','.026+CDi+CDp','','Coeficiente total.'),('D','qS*CD','N','Equilibrio horizontal requiere este empuje.'),('P','D*72','W','Potencia aerodinámica.'),('Mach','72/sqrt(1.4*287.05287*T)','','Comprobar Mach bajo.'),('CLmargin','1.45-CL','','Margen de coeficiente respecto de pérdida.'),('A','.5*rho*S*.026','kg/m','Coeficiente del término cuadrático de velocidad.'),('B','2*K*34000**2/(rho*S)','kg*m**3/s**4','Coeficiente del término inverso cuadrático.'),('Vmin','(B/A)**.25','m/s','Resolver la condición de derivada nula.'),('Dmin','2*sqrt(A*B)','N','Sustituir en resistencia.'),('Td','.8*D','N','Empuje tras la reducción prescrita.'),('Delta','Td**2-4*A*B','N**2','Discriminante negativo: ningún equilibrio nivelado del modelo.'),('Tplus','1.2*Dmin','N','Empuje de la última cuestión.'),('Dp','Tplus**2-4*A*B','N**2','Discriminante del caso que sí admite raíces.'),('Vlo','sqrt((Tplus-sqrt(Dp))/(2*A))','m/s','Raíz inferior positiva.'),('Vhi','sqrt((Tplus+sqrt(Dp))/(2*A))','m/s','Raíz superior positiva.'),('CLlo','34000/(.5*rho*S*Vlo**2)','','Aplicar límite de sustentación a la primera raíz.'),('CLhi','34000/(.5*rho*S*Vhi**2)','','Repetir para la segunda raíz; el equilibrio no prueba estabilidad.')]),
3:(r'Para ascenso se calcula primero la resistencia nivelada y se usa la aproximación declarada de exceso de potencia. Para giro se exige $L=nW$, por lo que cambia la resistencia inducida. El cohete, la órbita y los circuitos se resuelven con balances separados; no se iguala velocidad orbital a incremento ideal de velocidad.',
 [('qS','.5*.90*65**2*20','N','Escala de fuerza.'),('CL','36000/qS','','Sustentación nivelada.'),('CD','.024+.055*CL**2','','Polar nivelada.'),('D','qS*CD','N','Resistencia nivelada.'),('hdot','(4300-D)*65/36000','m/s','Exceso de potencia dividido por peso, aproximando sustentación por peso.'),('n','1/cos(pi/4)','','Equilibrio vertical del giro coordinado.'),('CLt','n*36000/qS','','Sustentación requerida en giro.'),('CDt','.024+.055*CLt**2','','Polar con el nuevo coeficiente.'),('Dt','qS*CDt','N','Resistencia de giro.'),('marginL','1.45-CLt','','Margen de sustentación positivo.'),('marginT','4300-Dt','N','Margen de empuje negativo: el giro no se sostiene.'),('dv','298*9.80665*log(1800/650)','m/s','Integrar ecuación del cohete con impulso específico constante.'),('r','6971*1000','m','Convertir radio orbital a SI.'),('Vc','sqrt(3.986004418e14/r)','m/s','Igualar aceleración gravitatoria y centrípeta.'),('period','2*pi*r/Vc','s','Longitud de la órbita dividida por velocidad circular.'),('Ph','14e6*3e-4','W','Potencia hidráulica útil.'),('Pin','Ph/.80','W','Dividir por rendimiento global.'),('I','1200/28','A','Corriente nominal con la tensión ideal de carga especificada.'),('Ploss','I**2*.040','W','Disipación de ida y retorno.'),('drop','I*.040','V','Caída de tensión asociada; cuantifica la aproximación de tensión nominal.')])}
path=BOOK/'content/exam-solutions.tex';text=path.read_text();reports=[]
for n,(strategy,data) in ROUTES.items():
 body,checks=numeric_steps([dict(target=k,expression=e,unit=u,why=w) for k,e,u,w in data])
 (BOOK/'solutions/generated'/f'EX{n}.tex').write_text(r'\subsection*{Procedimiento y operaciones del simulacro '+str(n)+'}\n'+strategy+'\n\n'+body+'\n')
 marker=r'\section{Simulacro '+str(n)+'}';a=text.index(marker);b=text.find(r'\section{',a+len(marker));b=len(text) if b<0 else b
 token=r'\input{../solutions/generated/EX'+str(n)+'.tex}'
 if token not in text[a:b]:text=text[:b]+'\n'+token+'\n'+text[b:]
 reports.append(dict(exam=n,steps=checks))
path.write_text(text)
(BOOK/'reports/exam-solution-procedures.json').write_text(json.dumps(dict(scope='Original numeric exam data and authored derivations; no independent approval',records=reports),ensure_ascii=False,indent=2)+'\n')
